SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "徐约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启三年条所见人物：徐约。", "biography": null, "status": "draft", "id": "478eb858-866b-5fb9-903c-5858171f2d8f"}, {"name": "张雄", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：张雄。", "biography": null, "status": "draft", "id": "c143e925-2fd8-5be6-abed-b89d550f0724"}, {"name": "高骈", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的高骈，在此段中为受呈者。", "biography": null, "status": "draft", "id": "c4d5b35a-b520-57df-87da-baff9480b7e4"}, {"name": "秦宗权", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的秦宗权，在此段中为遣兵者。", "biography": null, "status": "draft", "id": "4ab9b100-f137-522e-9b11-1ef372de9edf"}, {"name": "毕师铎", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：毕师铎。", "biography": null, "status": "draft", "id": "f1541150-4966-5c04-9879-060cf391f2c2"}, {"name": "吕用之", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的吕用之，在此段中为被指控者。", "biography": null, "status": "draft", "id": "cd08ae2a-9825-5636-a942-312bb29aed61"}, {"name": "郑汉章", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：郑汉章。", "biography": null, "status": "draft", "id": "6627883e-83a2-5c78-b77d-a62093d2195c"}, {"name": "张神剑（高邮）", "aliases": ["张神剑"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张神剑（高邮）。", "biography": null, "status": "draft", "id": "d6d78194-79d3-5a9c-87dd-21fc50ffd8c1"}, {"name": "张守一", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：张守一。", "biography": null, "status": "draft", "id": "d1af1f2f-4716-556c-aa44-b30041a663b8"}, {"name": "诸葛殷", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：诸葛殷。", "biography": null, "status": "draft", "id": "fafc93ce-fe25-550c-a1d7-9680812979bb"}, {"name": "朱珍", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷255中和四年条记载的朱珍，在此段中为击退者。", "biography": null, "status": "draft", "id": "863c86d4-bcc1-57f7-a877-4c9d05eed8ca"}, {"name": "朱温", "aliases": ["朱全忠", "朱晃", "梁太祖"], "era": "五代十国", "birth_year": null, "death_year": 912, "description": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "biography": "后梁建立者。907年在大梁称帝，912年在宫廷政变中被杀。", "status": "draft", "id": "0555e455-34d4-54ef-b93e-b0e6425018ab"}, {"name": "秦贤", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：秦贤。", "biography": null, "status": "draft", "id": "ca7ed1a7-1af6-567f-b170-8e77c7cc36fb"}, {"name": "张晊", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256中和四年条所见人物：张晊。", "biography": null, "status": "draft", "id": "4c26e1dc-5a81-51f0-b046-cee75fe25e88"}, {"name": "郭言", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：郭言。", "biography": null, "status": "draft", "id": "d890bf28-055c-53ab-a5fb-de04032e2f7b"}, {"name": "孙约", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：孙约。", "biography": null, "status": "draft", "id": "b7f09374-86d0-5eaa-8d03-60d8fef12186"}, {"name": "秦彦", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷256光启二年条所见人物：秦彦。", "biography": null, "status": "draft", "id": "720ca49a-19c0-563d-9b63-48f1e8e448f8"}, {"name": "许戡", "aliases": [], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷257光启三年条所见人物：许戡。", "biography": null, "status": "draft", "id": "70e00da0-29ab