ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "徐约逐张雄，张雄率部逃海", "start_year": 887, "end_year": 887, "time_original": "光启三年夏四月甲辰朔", "dynasty": "唐", "description": "徐约逐苏州刺史张雄；张雄率部逃入海中。", "phases": [], "location_name": "苏州、海上", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "65ad7c36-a844-5abd-9742-896301954a8b"}, {"title": "高骈遣毕师铎屯高邮", "start_year": 887, "end_year": 887, "time_original": "光启三年四月乙巳前；具体日未载", "dynasty": "唐", "description": "高骈听闻秦宗权将攻淮南，遣毕师铎率兵屯高邮。", "phases": [], "location_name": "高邮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "df881797-be1b-53f6-bbe2-3315ea19eea6"}, {"title": "毕师铎与吕用之关系恶化", "start_year": 887, "end_year": 887, "time_original": "毕师铎赴高邮前；具体年日未载", "dynasty": "唐", "description": "毕师铎因吕用之掌权并探访其妾而愤惧；赴高邮前，吕用之反而厚待，毕师铎更加疑虑。", "phases": [], "location_name": "广陵、高邮方向", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "53166f3d-e9ff-52b6-a1f0-6c64850eac5b"}, {"title": "毕师铎联郑汉章举兵", "start_year": 887, "end_year": 887, "time_original": "光启三年四月乙巳前夜", "dynasty": "唐", "description": "毕师铎疑吕用之将害己，与郑汉章会合；郑汉章发镇兵及居民跟随。张神剑被毕师铎问及密报，称并无文书，后与之共同起事。", "phases": [], "location_name": "高邮", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "4468d0f3-0706-583e-a074-187a8e44d625"}, {"title": "毕师铎被推行营使，发檄后出高邮", "start_year": 887, "end_year": 887, "time_original": "光启三年四月乙巳至戊申", "dynasty": "唐", "description": "乙巳众人推毕师铎为行营使，发文告称要诛吕用之、张守一、诸葛殷；郑汉章为副使、张神剑为都指挥使。戊申毕师铎、郑汉章率军离高邮。", "phases": [], "location_name": "高邮、淮南", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bb45e1d4-b22d-59fb-af80-dee651957da6"}, {"title": "吕用之隐瞒毕师铎起事军情", "start_year": 887, "end_year": 887, "time_original": "光启三年四月庚戌", "dynasty": "唐", "description": "侦骑把毕师铎军情报告高骈，吕用之将报告隐瞒。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "9c638708-67e8-5338-a0a4-931747e02913"}, {"title": "朱珍募兵归大梁并袭青州得马", "start_year": 887, "end_year": 887, "time_original": "光启三年四月辛亥", "dynasty": "唐", "description": "朱珍赴淄青募兵，又袭青州取马；辛亥率部回大梁。朱全忠得知后喜。", "phases": [], "location_name": "淄青、青州、大梁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "76fef46a-7c99-5c0c-a536-b981079c433b"}, {"title": "朱全忠突击秦贤营寨", "start_year": 887, "end_year": 887, "time_original": "光启三年四月辛亥后", "dynasty": "唐", "description": "秦贤、张晊率蔡州军攻汴州周边；朱全忠趁秦贤未防备率军突击，连取四寨。", "phases": [], "location_name": "汴州、板桥", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "7ee9e63b-be81-5155-9550-3b706648e58d"}, {"title": "朱全忠遣郭言赴河阳等地募兵", "start_year": 887, "end_year": 887, "time_original": "秦贤营寨被攻后；具体日未载", "dynasty": "唐", "description": "朱全忠遣郭言往河阳、陕、虢募兵，郭言带兵返回。", "phases": [], "location_name": "河阳、陕、虢", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "e74f448a-268d-5aca-b575-3708d5432b1b"}, {"title": "毕师铎兵至广陵城下，吕用之出战后闭城", "start_year": 887, "end_year": 887, "time_original": "光启三年四月壬子", "dynasty": "唐", "description": "毕师铎军到广陵城下；吕用之率兵出城作战使对方暂退，随后断桥闭门守城。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "ada6f53c-e61e-53b6-a701-fa1d2e330ae2"}, {"title": "高骈知毕师铎之变，质问吕用之", "start_year": 887, "end_year": 887, "time_original": "光启三年四月壬子", "dynasty": "唐", "description": "高骈听闻毕师铎起事后质问吕用之；吕用之淡化军情，高骈表示已察觉其妄言。", "phases": [], "location_name": "广陵延和阁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "bd42887b-859f-5306-879a-64d51680b2da"}, {"title": "毕师铎向宣州秦彦求援", "start_year": 887, "end_year": 887, "time_original": "光启三年四月癸丑", "dynasty": "唐", "description": "毕师铎遣孙约与其子赴宣州请求秦彦援军，许诺攻下广陵后迎秦彦为帅。", "phases": [], "location_name": "广陵、宣州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f8520d3a-dfa5-57e9-9f5c-4e3ec07f34a4"}, {"title": "高骈命吕用之遣人持札劝毕师铎", "start_year": 887, "end_year": 887, "time_original": "光启三年四月癸丑后", "dynasty": "唐", "description": "高骈向吕用之问清事由，表示先遣可信将领持手札劝毕师铎，若不从再另行处置。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "db1ae256-e2aa-512b-b654-4caa4d4572e3"}, {"title": "毕师铎杀吕用之所遣许戡", "start_year": 887, "end_year": 887, "time_original": "光启三年四月甲寅", "dynasty": "唐", "description": "吕用之派许戡带高骈手札、誓状与酒食慰劳毕师铎；毕师铎拒绝接谈，将许戡杀害。", "phases": [], "location_name": "广陵城外", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "8df21dae-fe41-5164-8af6-fd7cb899b3af"}, {"title": "毕师铎射书入城，吕用之焚毁", "start_year": 887, "end_year": 887, "time_original": "光启三年四月乙卯", "dynasty": "唐", "description": "毕师铎将书信射入城内，吕用之未开读即焚毁。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "f98cf3cf-2f2f-500a-b8db-2236e76a0241"}, {"title": "吕用之带甲士见高骈，高吕决裂", "start_year": 887, "end_year": 887, "time_original": "光启三年四月丁巳", "dynasty": "唐", "description": "吕用之带兵进入高骈所在的延和阁下，高骈惊而责其无故带兵，命逐出。吕用之离开子城，自此两人决裂。", "phases": [], "location_name": "广陵延和阁", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "b64800a1-30ae-5cdc-bf89-e9a8eb5c66bf"}, {"title": "高骈任其从子高杰掌都牢城", "start_year": 887, "end_year": 887, "time_original": "光启三年四月戊午", "dynasty": "唐", "description": "高骈与从子高杰密议军务，任高杰为都牢城使并给亲信兵。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "98889b09-812f-5e82-86ff-4f34176935e5"}, {"title": "吕用之强迫广陵民众登城守卫", "start_year": 887, "end_year": 887, "time_original": "光启三年四月戊午前后", "dynasty": "唐", "description": "吕用之命人搜捕城中壮丁，连朝士书生也被迫登城守卫，常日不得休息；家人难以找到他们。", "phases": [], "location_name": "广陵", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "仅保留史载地名；未核坐标。", "status": "draft", "id": "c8b6e922-3dce-5857-b92d-dbc50328b783"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.person_relationship (id, person_a, person_b, relation_type, description, status)
SELECT id, person_a, person_b, relation_type, description, status FROM jsonb_populate_recordset(NULL::public.person_relationship, '[{"relation_type": "从子", "description": "《通鉴》卷257称高杰为高骈从子。", "status": "draft", "id": "79b21084-841f-5c5e-86bf-d5a46706dde0", "person_a": "c4d5b35a-b520-57df-87da-baff9480b7e4", "person_b": "c31d3cc1-f8d0-5d72-858b-f632f2b5ff73"}]'::jsonb)
